import z3
s = z3.Solver()
weeks = 7
players = 27
groups = 9
group_size = 3
groups_var = [[z3.Int(f'g{w}_{p}') for p in range(players)] for w in range(weeks)]
for w in range(weeks):
    for p in range(players):
        s.add(groups_var[w][p] >= 0, groups_var[w][p] < groups)
for w in range(weeks):
    for g in range(groups):
        count = z3.Sum([z3.If(groups_var[w][p] == g, 1, 0) for p in range(players)])
        s.add(count == group_size)
for p1 in range(players):
    for p2 in range(p1+1, players):
        same_count = z3.Sum([z3.If(groups_var[w][p1] == groups_var[w][p2], 1, 0) for w in range(weeks)])
        s.add(same_count <= 1)
print(s.check())

import z3
weeks = 7
players = 27
groups = 9
group_size = 3
s = z3.Solver()
groups_var = [[z3.Int(f'g{w}_{p}') for p in range(players)] for w in range(weeks)]
for w in range(weeks):
    for p in range(players):
        s.add(groups_var[w][p] >= 0, groups_var[w][p] < groups)
for w in range(weeks):
    for g in range(groups):
        count = z3.Sum([z3.If(groups_var[w][p] == g, 1, 0) for p in range(players)])
        s.add(count == group_size)
for p1 in range(players):
    for p2 in range(p1+1, players):
        same_count = z3.Sum([z3.If(groups_var[w][p1] == groups_var[w][p2], 1, 0) for w in range(weeks)])
        s.add(same_count <= 1)
if s.check() == z3.sat:
    m = s.model()
    solution = []
    for w in range(weeks):
        for p in range(players):
            solution.append(m[groups_var[w][p]].as_long())
    print(solution)
else:
    print("unsat")
